CREATE TABLE IF NOT EXISTS smart_catalog_products (id TEXT PRIMARY KEY,name TEXT NOT NULL,category TEXT,description TEXT,price REAL,currency TEXT NOT NULL DEFAULT 'BRL',status TEXT NOT NULL DEFAULT 'draft',source TEXT NOT NULL DEFAULT 'nexora-smart-catalog',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);\nCREATE INDEX IF NOT EXISTS idx_smart_catalog_created ON smart_catalog_products(created_at DESC);\n